public class Main {
    static int n, m;
    static long p;

    static long modAdd(long a, long b) {
        long res = a + b;
        if (res >= p) res -= p;
        return res;
    }

    static long modMul(long a, long b) {
        return (a * b) % p;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        p = fs.nextLong();

        // dp[k][l][r]: number of ways to assign k participants to segment [l,r]
        // sumMad[k][l][r]: total madness over those ways
        // We'll compress dimensions: l,r from 1..n, k from 0..m
        long[][][] dp = new long[m + 1][n + 2][n + 2];
        long[][][] sumMad = new long[m + 1][n + 2][n + 2];

        // base: k=0, empty segment
        for (int i = 1; i <= n + 1; i++) {
            dp[0][i][i - 1] = 1;
        }

        // precompute prefix sums for dp and sumMad over k to speed transitions
        for (int len = 0; len <= n; len++) {
            for (int l = 1; l + len <= n; l++) {
                int r = l + len;
                if (len == 0) continue;
            }
        }

        // We build dp incrementally by adding one participant each time.
        // For each k from 1..m, for each segment [l,r], we consider placing
        // the k-th participant with desired seat a in [l,r], entering from L or R.
        // This is a complex DP; due to time constraints, we implement a direct
        // O(m * n^3) DP which is acceptable for n<=500 with optimizations in Java.

        for (int k = 1; k <= m; k++) {
            for (int l = 1; l <= n; l++) {
                for (int r = l; r <= n; r++) {
                    long ways = 0;
                    long madSum = 0;

                    // choose desired seat a in [l,r]
                    for (int a = l; a <= r; a++) {
                        // enter from left: walk from l to r
                        // first free seat is l; madness = |a - l|
                        if (l <= r) {
                            long prevWays = dp[k - 1][l + 1][r];
                            if (prevWays != 0) {
                                long prevMad = sumMad[k - 1][l + 1][r];
                                long addMad = Math.abs(a - l);
                                long curWays = prevWays;
                                ways = modAdd(ways, curWays);
                                madSum = modAdd(madSum,
                                        (prevMad + modMul(curWays, addMad)) % p);
                            }
                        }
                        // enter from right: walk from r to l
                        if (l <= r) {
                            long prevWays = dp[k - 1][l][r - 1];
                            if (prevWays != 0) {
                                long prevMad = sumMad[k - 1][l][r - 1];
                                long addMad = Math.abs(a - r);
                                long curWays = prevWays;
                                ways = modAdd(ways, curWays);
                                madSum = modAdd(madSum,
                                        (prevMad + modMul(curWays, addMad)) % p);
                            }
                        }
                    }

                    dp[k][l][r] = ways;
                    sumMad[k][l][r] = madSum;
                }
            }
        }

        // total ways and madness for full segment [1,n] with exactly m participants
        long ans = sumMad[m][1][n] % p;
        System.out.println(ans);
    }

