    static int n, m;
    static long p;
    static long[][] C;
    static long[] fact, invFact;
    static long[][] dp;
    static long[][] sumMad;

    static long modPow(long a, long e) {
        long r = 1 % p;
        a %= p;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % p;
            a = (a * a) % p;
            e >>= 1;
        }
        return r;
    }

    static void precomputeComb(int maxN) {
        C = new long[maxN + 1][maxN + 1];
        for (int i = 0; i <= maxN; i++) {
            C[i][0] = C[i][i] = 1 % p;
            for (int j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % p;
            }
        }
    }

    static void precomputeFact(int maxN) {
        fact = new long[maxN + 1];
        invFact = new long[maxN + 1];
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) fact[i] = (fact[i - 1] * i) % p;
        invFact[maxN] = modPow(fact[maxN], p - 2);
        for (int i = maxN; i > 0; i--) invFact[i - 1] = (invFact[i] * i) % p;
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return (((fact[n] * invFact[k]) % p) * invFact[n - k]) % p;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        p = fs.nextLong();

