            for (int k = 0; k <= m; k++) {
                long ways = 0;
                long madSum = 0;

                for (int left = 0; left <= k; left++) {
                    int right = k - left;
                    if (left > len || right > len) continue;

                    long waysLeft = dp[len - 1][left];
                    long waysRight = dp[len - 1][right];
                    if (waysLeft == 0 || waysRight == 0) continue;

                    long waysHere = (waysLeft * waysRight) % p;
                    waysHere = (waysHere * C[len - 1][left]) % p;

                    long madLeft = sumMad[len - 1][left];
                    long madRight = sumMad[len - 1][right];

