    static final int MAXN = 500;
    static int n, m;
    static long mod;

    static long[][] C = new long[MAXN + 1][MAXN + 1];
    static long[] fact = new long[MAXN + 1];
    static long[] invFact = new long[MAXN + 1];

    static long modPow(long a, long e) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) != 0) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    static long inv(long x) {
        return modPow(x, mod - 2);
    }

    static void precompute() {
        for (int i = 0; i <= n; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
            }
        }
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
        invFact[n] = inv(fact[n]);
        for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % mod;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        mod = fs.nextLong();

        precompute();

        long ans = 0;

        // iterate over all subsets S of participants that go left (others go right)
        int totalMasks = 1 << m;
        for (int mask = 0; mask < totalMasks; mask++) {
            int kL = Integer.bitCount(mask);
            int kR = m - kL;

            // number of ways to choose kL distinct start positions for L and kR for R
            if (kL > n || kR > n) continue;

            long waysA = C[n][kL] * C[n][kR] % mod;

            // number of permutations of these starts (participants are ordered)
            long waysPerm = fact[kL] * fact[kR] % mod;

            // simulate for this pattern of directions
            // we need expected total madness over all choices of distinct starts
            // but due to symmetry, each pattern contributes same madness
            // so we can simulate with fixed distinct positions and multiply

            // choose arbitrary distinct positions: first kL for L, last kR for R
            int[] startL = new int[kL];
            int[] startR = new int[kR];
            for (int i = 0; i < kL; i++) startL[i] = i + 1;
            for (int i = 0; i < kR; i++) startR[i] = n - i;

            // map participants to starts according to order and mask
            int[] assigned = new int[m];
            int idxL = 0, idxR = 0;
            for (int i = 0; i < m; i++) {
                if (((mask >> i) & 1) == 1) {
                    assigned[i] = startL[idxL++];
                } else {
                    assigned[i] = startR[idxR++];
                }
            }

            boolean[] occ = new boolean[n + 1];
            long totalMad = 0;
            boolean ok = true;

            for (int i = 0; i < m; i++) {
                int a = assigned[i];
