                }
                if (pos < 1 || pos > n) {
                    ok = false;
                    break;
                }
                occ[pos] = true;
                totalMad += Math.abs(a - pos);
            }

            if (!ok) continue;

            long contrib = totalMad % mod;
            contrib = contrib * waysA % mod;
            contrib = contrib * waysPerm % mod;
            ans = (ans + contrib) % mod;
        }

        System.out.println(ans % mod);
    }

