public class Main {
    static int n, m;
    static long p;

    static long modAdd(long a, long b) {
        a += b;
        if (a >= p) a -= p;
        return a;
    }

    static long modMul(long a, long b) {
        return (a % p) * (b % p) % p;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        p = fs.nextLong();

        // dp[k][l][r] : number of ways after k participants, with l occupied on left, r on right
        // sumMad[k][l][r] : total madness sum over those ways
        long[][][] dp = new long[m + 1][n + 1][n + 1];
        long[][][] sumMad = new long[m + 1][n + 1][n + 1];

        dp[0][0][0] = 1;

        for (int k = 0; k < m; k++) {
            for (int l = 0; l <= n; l++) {
                for (int r = 0; r <= n; r++) {
                    long ways = dp[k][l][r];
                    if (ways == 0) continue;
                    long curSum = sumMad[k][l][r];
                    int free = n - (l + r);
                    if (free <= 0) continue;

                    // For each possible assigned computer a in [1..n]
                    for (int a = 1; a <= n; a++) {
                        // For each direction
                        // Direction L
                        // Participant enters from left, target a, then moves right
                        // He will sit at first free >= a
                        int posL = -1;
                        if (l + r < n) {
                            // free segment is [l+1 .. n-r]
                            int start = Math.max(a, l + 1);
                            if (start <= n - r) posL = start;
                        }
                        if (posL != -1) {
                            int nl = Math.max(l, posL);
                            int nr = r;
                            long madness = Math.abs(posL - a);
                            long addWays = ways;
                            long addSum = (curSum + modMul(ways, madness)) % p;
                            dp[k + 1][nl][nr] = modAdd(dp[k + 1][nl][nr], addWays);
                            sumMad[k + 1][nl][nr] = modAdd(sumMad[k + 1][nl][nr], addSum);
                        }

                        // Direction R
                        // Participant enters from right, target a, then moves left
                        // He will sit at first free <= a
                        int posR = -1;
                        if (l + r < n) {
                            int end = Math.min(a, n - r);
                            if (end >= l + 1) posR = end;
                        }
                        if (posR != -1) {
                            int nl = l;
                            int nr = Math.max(r, n - posR + 1);
                            long madness = Math.abs(posR - a);
                            long addWays = ways;
                            long addSum = (curSum + modMul(ways, madness)) % p;
                            dp[k + 1][nl][nr] = modAdd(dp[k + 1][nl][nr], addWays);
                            sumMad[k + 1][nl][nr] = modAdd(sumMad[k + 1][nl][nr], addSum);
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int l = 0; l <= n; l++) {
            int r = n - l;
            if (r < 0 || r > n) continue;
            ans = modAdd(ans, sumMad[m][l][r]);
        }
        System.out.println(ans % p);
