import java.io.*;
import java.util.*;

public class Main {
    static final int MAXN = 500;
    static long MOD;
    static long[][] C = new long[MAXN + 1][MAXN + 1];
    static long[] fact = new long[MAXN + 1];
    static long[] invFact = new long[MAXN + 1];

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) != 0) r = (r * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return r;
    }

    static long inv(long x) {
        return modPow(x, MOD - 2);
    }

    static void precompute(int n) {
        for (int i = 0; i <= n; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = inv(fact[n]);
        for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return C[n][k];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();
        MOD = fs.nextLong();

        precompute(n);

        long[][] dp = new long[n + 1][m + 1];
        long[][] mad = new long[n + 1][m + 1];

        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            dp[i][0] = 1;
            mad[i][0] = 0;
            for (int k = 1; k <= Math.min(i, m); k++) {
                long ways = 0;
                long sumMad = 0;

                for (int t = 1; t <= k; t++) {
                    int prev = i - 1;
                    int prevK = k - t;
                    if (prevK > prev) continue;

                    long waysPrev = dp[prev][prevK];
                    if (waysPrev == 0) continue;

                    long waysAssign = comb(k - 1, t - 1);
                    long waysB = modPow(2, k - t);

                    long curWays = waysPrev * waysAssign % MOD * waysB % MOD;

                    long sumDist = 0;
                    for (int d = 1; d <= i; d++) {
                        long cnt = 0;
                        if (d <= i - 1) {
                            cnt = 2L * (i - d);
                        } else if (d == i) {
                            cnt = 1;
                        }
                        if (cnt == 0) continue;
                        long contrib = cnt % MOD * d % MOD;
                        sumDist = (sumDist + contrib) % MOD;
                    }

                    long totalMadBlock = sumDist % MOD;

                    long prevMad = mad[prev][prevK];

                    long curMad = (prevMad * curWays % MOD + waysPrev * waysAssign % MOD * waysB % MOD * totalMadBlock % MOD) % MOD;

                    ways = (ways + curWays) % MOD;
                    sumMad = (sumMad + curMad) % MOD;
                }

                dp[i][k] = ways;
                mad[i][k] = sumMad;
            }
        }

        long ans = mad[n][m] % MOD;
        System.out.println(ans);
    }

    // FastScanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
